def verify_access_log(log_path: str, allowed_ips: list[str]) -> list[str]:
    allowed = set(allowed_ips)
    unauthorized = []
    with open(log_path) as f:
        for line in f:
            if line.strip():
                ip = line.split(maxsplit=1)[0]
                if ip not in allowed:
                    unauthorized.append(ip)
    return unauthorized
```

