def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    threats = ("SELECT", "DROP", "<SCRIPT>", "../", "CMD")
    return [
        p for p in packet_log
        if p.get("status") in (401, 403)
        or p.get("port") in {22, 23, 3389}
        or any(t in str(p.get("payload", "")).upper() for t in threats)
    ]
```

