import stat
from pathlib import Path

def audit_file_permissions(directory: str) -> list[dict]:
    findings = []
    for p in Path(directory).rglob("*"):
        if p.is_file():
            m = p.stat().st_mode
            if m & stat.S_IWOTH:
                findings.append({
                    "path": str(p),
                    "mode": oct(m)[-3:],
                    "issue": "world-writable"
                })
    return findings
```

