            if line:
                key, *val = line.split(None, 1)
                current[key] = val[0] if val else ''

    rec = {}
    desired = {
        'PermitRootLogin': 'no',
        'PasswordAuthentication': 'no',
        'PubkeyAuthentication': 'yes',
        'PermitEmptyPasswords': 'no',
        'X11Forwarding': 'no',
        'Protocol': '2',
        'MaxAuthTries': '3',
        'IgnoreRhosts': 'yes',
        'HostbasedAuthentication': 'no',
    }

    for key, val in desired.items():
        cur = current.get(key)
        if cur is None:
            rec[key] = f"Saknas. Sätt till '{val}'."
        elif cur.lower() != val:
            rec[key] = f"Är '{cur}'. Rekommenderas: '{val}'."

    return rec
